import java.io.IOException;

public class Codeforces {
    final static int P = 1000000007;

    private static int nextInt() throws IOException {
        int c = System.in.read();
        while (c != -1 && c <= ' ') {
            c = System.in.read();
        }
        if (c == -1) {
            throw new IOException("No input");
        }
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = System.in.read();
        } else if (c == '+') {
            c = System.in.read();
        }
        int value = 0;
        while (c != -1 && c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = System.in.read();
        }
        return value * sign;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[][] table = new int[n + 1][n + 1];

        for (int i = 0; i <= n; i++) {
            for (int j = i; j <= n; j++) {
                if (i == 0 && j == 0) {
                    continue;
                }
                if (i == 0) {
                    table[i][j] = (table[i][j - 1] + ((i + j) & 1)) % P;
                } else {
                    table[i][j] = (table[i - 1][j] + table[i][j - 1] + ((i + j) & 1)) % P;
                }
            }
        }

        System.out.println(table[n][n]);
    }
}
